 * @param node a node to rotate
 * @return a new parent of the {@code node}
 */
private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("Node to rotate cannot be null");
    }
    // create a new parent for the node
    TreeNode<T> newParent = new TreeNode<>(node.getValue());
    newParent.setLeftChild(node.getLeftChild());
    newParent.setRightChild(node.getRightChild());
    // replace the node with its right child
    node.setRightChild(newParent);
    return newParent;
}
