        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i == str.length() - 1) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextCh = str.charAt(i + 1);
            if (nextCh == 'n') {
                sb.append('\n');
                i++;
            } else if (nextCh == 'r') {
                sb.append('\r');
                i++;
            } else if (nextCh == 't') {
                sb.append('\t');
                i++;
            } else if (nextCh == 'b') {
